import (
	"html"
	"testing"
)

func BenchmarkEscapeString(b *testing.B) {
	msg := "<script>alert('XSS')</script>"
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		html.EscapeString(msg)
	}
}

func BenchmarkNoEscape(b *testing.B) {
	msg := "<script>alert('XSS')</script>"
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		// No escaping, just use the message as is
		_ = msg
	}
}

go
import (
	"testing"
	"html"
)

func BenchmarkSanitizeMessage(b *testing.B) {
	msg := "Hello, World!"
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		sanitizedMsg := html.EscapeString(msg)
		_ = sanitizedMsg
	}
}

func BenchmarkGenerateReceiveLog(b *testing.B) {
	msg := "Test Message"
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		timestamp := time.Now().Format(time.RFC3339Nano)
		logEntry := "[" + timestamp + "] Received: " + html.EscapeString(msg)
		_ = logEntry
	}
}
